import StatisticsCards from '@/components/cards/StatisticsCards';
import UserMinusIcon from '@/components/icons/UserMinusIcon';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Card } from '@/types/statistics';
import { useEffect, useState } from 'react';

interface AttendanceStats {
    total_requests: number;
    total_approved: number;
    total_pending: number;
    total_rejected: number;
}

export default function AttendaceRequestsStatistics() {
    const [stats, setStats] = useState<AttendanceStats | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.holiday.dashboard,
                    queryParams: { my_requests: 1 },
                });
                if (!cancelled) setStats(res.data.data);
            } catch {
                if (!cancelled) setStats(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards: Card[] = [
        { text: 'عدد الطلبات', icon: <UserMinusIcon />, num: stats?.total_requests, percent: 0 },
        { text: 'موافق عليها', icon: <UserMinusIcon />, num: stats?.total_approved, percent: 0 },
        { text: 'قيد المراجعة', icon: <UserMinusIcon />, num: stats?.total_pending, percent: 0 },
        { text: 'مرفوضة', icon: <UserMinusIcon />, num: stats?.total_rejected, percent: 0 },
    ];

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
